#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <functional>
#include <sstream>
#include <regex>
#include <queue>
#include <mutex>
#include <memory>

namespace mq {

struct Message {
    std::string topic;
    std::string payload;
    std::map<std::string, std::string> headers;
};

struct UserContext {
    std::string user_id;
    std::string role; // "admin", "service", "user"
    std::vector<std::string> allowed_topics;
};

class GraphQLQueryBuilder {
public:
    static std::string sanitize_field(const std::string& field) {
        // Allow alphanumeric, underscore, and dots for nested fields
        std::regex valid_pattern("^[a-zA-Z_][a-zA-Z0-9_.]*$");
        if (!std::regex_match(field, valid_pattern)) {
            return "";
        }
        return field;
    }

    static std::string sanitize_value(const std::string& value) {
        std::string result;
        for (char c : value) {
            if (c == '"') result += "\\\"";
            else if (c == '\\') result += "\\\\";
            else if (c == '\n') result += "\\n";
            else if (c == '\r') result += "\\r";
            else result += c;
        }
        return result;
    }

    static std::string build_query(const std::string& operation,
                                    const std::map<std::string, std::string>& params,
                                    const std::vector<std::string>& fields) {
        std::ostringstream query;
        query << "{ " << operation << "(";
        bool first = true;
        for (const auto& [key, value] : params) {
            std::string safe_key = sanitize_field(key);
            if (safe_key.empty()) continue;
            if (!first) query << ", ";
            query << safe_key << ": \"" << sanitize_value(value) << "\"";
            first = false;
        }
        query << ") { ";
        for (const auto& f : fields) {
            std::string safe_field = sanitize_field(f);
            if (!safe_field.empty()) query << safe_field << " ";
        }
        query << "} }";
        return query.str();
    }
};

class RBACPolicy {
public:
    static bool can_access_topic(const UserContext& ctx, const std::string& topic) {
        if (ctx.role == "admin") return true;
        for (const auto& t : ctx.allowed_topics) {
            if (t == topic) return true;
        }
        return false;
    }

    static bool can_query_field(const UserContext& ctx, const std::string& field) {
        static const std::vector<std::string> restricted = {"password", "secret", "token", "private_key"};
        if (ctx.role == "admin") return true;
        for (const auto& r : restricted) {
            if (field.find(r) != std::string::npos) return false;
        }
        return true;
    }

    static std::vector<std::string> filter_fields(const UserContext& ctx,
                                                    const std::vector<std::string>& requested) {
        std::vector<std::string> allowed;
        for (const auto& f : requested) {
            if (can_query_field(ctx, f)) {
                allowed.push_back(f);
            }
        }
        return allowed;
    }
};

class MessageProcessor {
public:
    struct QueryRequest {
        std::string operation;
        std::map<std::string, std::string> parameters;
        std::vector<std::string> fields;
    };

    std::string process_message(const Message& msg, const UserContext& ctx) {
        if (!RBACPolicy::can_access_topic(ctx, msg.topic)) {
            return "{\"error\": \"access_denied\"}";
        }

        QueryRequest req = parse_request(msg);

        // Apply RBAC field filtering
        req.fields = RBACPolicy::filter_fields(ctx, req.fields);

        // Always use the safe parameterized builder
        return GraphQLQueryBuilder::build_query(req.operation, req.parameters, req.fields);
    }

    QueryRequest parse_request(const Message& msg) {
        QueryRequest req;
        auto it = msg.headers.find("X-Operation");
        if (it != msg.headers.end()) {
            std::string op = GraphQLQueryBuilder::sanitize_field(it->second);
            req.operation = op;
        }

        it = msg.headers.find("X-Fields");
        if (it != msg.headers.end()) {
            std::istringstream ss(it->second);
            std::string field;
            while (std::getline(ss, field, ',')) {
                req.fields.push_back(field);
            }
        }

        // Parse parameters from payload as key=value pairs
        std::istringstream payload_stream(msg.payload);
        std::string line;
        while (std::getline(payload_stream, line)) {
            auto eq_pos = line.find('=');
            if (eq_pos != std::string::npos) {
                req.parameters[line.substr(0, eq_pos)] = line.substr(eq_pos + 1);
            }
        }

        return req;
    }
};

class Consumer {
private:
    std::queue<Message> queue_;
    std::mutex queue_mutex_;
    MessageProcessor processor_;
    std::map<std::string, UserContext> sessions_;

public:
    void register_session(const std::string& session_id, const UserContext& ctx) {
        sessions_[session_id] = ctx;
    }

    void enqueue(const Message& msg) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        queue_.push(msg);
    }

    std::string consume(const std::string& session_id) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        if (queue_.empty()) return "{\"status\": \"empty\"}";

        auto it = sessions_.find(session_id);
        if (it == sessions_.end()) return "{\"error\": \"invalid_session\"}";

        Message msg = queue_.front();
        queue_.pop();

        return processor_.process_message(msg, it->second);
    }
};

} // namespace mq

int main() {
    mq::Consumer consumer;

    mq::UserContext service_ctx{"svc-001", "service", {"events", "notifications"}};
    consumer.register_session("sess-abc", service_ctx);

    mq::Message msg;
    msg.topic = "events";
    msg.payload = "user_id=12345";
    msg.headers["X-Operation"] = "getUser";
    msg.headers["X-Fields"] = "id,name,email";

    consumer.enqueue(msg);
    std::string result = consumer.consume("sess-abc");
    std::cout << "Query: " << result << std::endl;

    return 0;
}
